import{_ as t,p as n,q as c,s as e,R as a,t as s,Y as o,n as d}from"./framework-e1bed10d.js";const p="/my-blog/assets/041_01-1e0d7e73.png",i={},h=e("h1",{id:"贷款状态与五级分类",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#贷款状态与五级分类","aria-hidden":"true"},"#"),a(" 贷款状态与五级分类")],-1),_={href:"https://mp.weixin.qq.com/s?__biz=MzIzNzQ5NjU5NQ==&mid=2247484991&idx=1&sn=71caa6957d436e09b9f7693dcb83e307&chksm=e8c6f643dfb17f55ba45569c7aa0a690e667486b5df64985c178bf5e3c9d0674d73a12227706",target:"_blank",rel:"noopener noreferrer"},l=o('<hr><p>五、贷款状态与五级分类</p><h3 id="一-从一逾两呆到五级分类" tabindex="-1"><a class="header-anchor" href="#一-从一逾两呆到五级分类" aria-hidden="true">#</a> （一）从一逾两呆到五级分类</h3><p>老一代银行把贷款状态叫“一逾两呆”：逾期、呆滞、呆账。现在的主流是五级分类：正常、关注、次级、可疑、损失。分类不是拍脑袋，而是由规则驱动的：逾期天数、诉讼状态、担保情况等。</p><p>借据状态管系统怎么记（六种状态见二（三））</p><h3 id="二-宽限期与逾期计算" tabindex="-1"><a class="header-anchor" href="#二-宽限期与逾期计算" aria-hidden="true">#</a> （二）宽限期与逾期计算</h3><p>每一期计划有还款起日和还款止日，起日到止日是正常还款期；还款止日之后通常还有一段宽限期（宽限天数由产品配置，常见3天），宽限期内还款不算逾期、不多收息；超过宽限期仍未还的，从宽限期结束的次日起算逾期天数，驱动状态变更和罚息计算。</p><p>超过宽限期仍未还款的，置为逾期，开始计罚息</p><h3 id="三-状态变更由谁驱动" tabindex="-1"><a class="header-anchor" href="#三-状态变更由谁驱动" aria-hidden="true">#</a> （三）状态变更由谁驱动</h3><p>贷款状态变更的驱动有两类：联机交易（放款、还款、退货、核销）和日终批量（逾期判定、形态转列）。联机驱动即时生效，批量驱动每天一次。状态的每一次迁移都要留痕，什么时候、由哪个交易、从什么状态变到什么状态，这是审计和监管报送的底账。</p><p>形态转列是五级分类在账务上的体现。逾期90天以上的贷款，本金不再按正常资产对待，已计提的利息也不再确认为收入——因为逾期90天以上，收回利息的可能性已经很低，按照谨慎性原则不能再确认收入。对应的科目转移与冲回分录，第六章讲核算日终时展开。</p><p>五级分类直接影响拨备计提。常见的参考计提比例是：正常类1%、关注类2%、次级类25%、可疑类50%、损失类100%（各机构在监管框架内略有差异）。</p><p><img src="'+p+'" alt="图片"></p><p>五级分类的核心判断标准是还款能力。正常类是借款人能够履行合同，没有足够理由怀疑贷款本息不能按时足额偿还；关注类是尽管借款人目前有能力偿还，但存在一些可能对偿还产生不利影响的因素；次级类是借款人的还款能力出现明显问题，完全依靠其正常营业收入无法足额偿还贷款本息，即使执行担保也可能造成一定损失；可疑类是借款人无法足额偿还贷款本息，即使执行担保也肯定要造成较大损失；损失类是在采取所有可能的措施和一切必要的法律程序之后，本息仍然无法收回或只能收回极少部分。</p><p>换个角度更好理解：贷款状态是业务视角，描述这笔贷款处在什么阶段（正常、逾期、结清这些日常说法）；五级分类是风险视角，描述风险程度（正常到损失五档）。</p>',15);function f(m,b){const r=d("ExternalLinkIcon");return n(),c("div",null,[h,e("blockquote",null,[e("p",null,[a("公众号：侃西东　·　发布日期：2026-10-27　·　"),e("a",_,[a("微信原文"),s(r)])])]),l])}const x=t(i,[["render",f],["__file","041.html.vue"]]);export{x as default};
